drawings.mermaid_code:
classDiagram
    class 정보입력부 {
        +String 구매자정보
        +String 판매자정보
        +String 구매정보
    }
    class 계약서제공부 {
        +createContract()
        +sendContract()
    }
    class 계약서수신부 {
        +receiveContract()
        +provideReceiptInfo()
    }
    class 가상계좌제공부 {
        +provideVirtualAccount()
    }
    class 입금정보제공부 {
        +provideDepositInfo()
    }
    class 비용지급부 {
        +processPayment()
    }
    class 서비스완료부 {
        +notifyCompletion()
    }
    class 정보저장부 {
        +saveInformation()
    }

    정보입력부 --> 계약서제공부 : "정보를 기반으로"
    계약서제공부 --> 계약서수신부 : "전자계약서를 수신"
    계약서수신부 --> 가상계좌제공부 : "구매정보를 기반으로"
    가상계좌제공부 --> 입금정보제공부 : "입금 정보를 전달"
    입금정보제공부 --> 비용지급부 : "입금 정보를 기반으로"
    비용지급부 --> 서비스완료부 : "분할 지급 완료 시"
    서비스완료부 --> 정보저장부 : "서비스 완료 정보를 저장"
